(function (global) {
  'use strict';
  const parse = (raw, fallback) => { try { return JSON.parse(raw) ?? fallback; } catch { return fallback; } };
  function session() { return parse(localStorage.getItem('datosVisionales') || localStorage.getItem('usuarioActivo'), {}); }
  function prefix(user = session()) {
    return 'prepicfes:u:' + (user.id_usuario || user.correo || 'anonymous') + ':';
  }
  const storage = {
    getItem: key => localStorage.getItem(prefix() + key),
    setItem: (key, value) => localStorage.setItem(prefix() + key, value),
  };
  function forUser(user) {
    const base = prefix(user);
    return { getItem:key=>localStorage.getItem(base+key), setItem:(key,value)=>localStorage.setItem(base+key,value), removeItem:key=>localStorage.removeItem(base+key) };
  }
  const pageUser = session();
  function sameSession(user = pageUser) {
    const now = session();
    return String(now.id_usuario || now.correo || '') === String(user.id_usuario || user.correo || '');
  }
  // Una pestaña abierta con otra cuenta no puede escribir sobre la sesión nueva.
  if (typeof global.fetch === 'function') {
    const nativeFetch = global.fetch.bind(global);
    global.fetch = (input, options = {}) => {
      const url = new URL(typeof input === 'string' ? input : input.url, location.href);
      if (url.origin === location.origin && url.pathname.startsWith('/api/') && !['/api/login','/api/registro','/api/health'].includes(url.pathname)) {
        if (!sameSession()) return Promise.reject(new Error('La cuenta cambió en otra pestaña. Recarga esta página.'));
        const headers = new Headers(options.headers || (typeof input === 'object' ? input.headers : undefined));
        if (pageUser.id_usuario) headers.set('X-Prep-User', String(pageUser.id_usuario));
        options = { ...options, headers };
        return nativeFetch(input, options).then(response => {
          if (!sameSession()) throw new Error('La cuenta cambió durante la solicitud. Recarga esta página.');
          return response;
        });
      }
      return nativeFetch(input, options);
    };
  }
  async function api(path, options = {}) {
    const response = await fetch(path, { credentials: 'include', ...options });
    const data = await response.json();
    if (!response.ok) { const error=new Error(data.mensaje || data.error || 'No se pudo completar la operación.');error.status=response.status;throw error; }
    return data;
  }
  const resultStore = forUser(pageUser);
  const resultKey = 'resultados_pendientes';
  const pendingResults = () => parse(resultStore.getItem(resultKey), {});
  function queueResult(payload) {
    const pending = pendingResults();
    pending[payload.id_resultado] = payload;
    resultStore.setItem(resultKey, JSON.stringify(pending));
  }
  function hasPendingResult(id) { return Object.hasOwn(pendingResults(), id); }
  async function sendPendingResults(payloads, index = 0) {
    if (index >= payloads.length || !sameSession() || !pageUser.id_usuario) return;
    const payload = payloads[index];
    await api('/api/simulacros', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(payload)});
    const remaining = pendingResults();
    delete remaining[payload.id_resultado];
    resultStore.setItem(resultKey, JSON.stringify(remaining));
    return sendPendingResults(payloads, index + 1);
  }
  let syncing;
  function syncResults() {
    if (syncing) return syncing;
    syncing = sendPendingResults(Object.values(pendingResults())).finally(() => { syncing = undefined; });
    return syncing;
  }
  function retryResults() { syncResults().catch(() => { /* Se conserva la cola para el próximo intento. */ }); }
  if (typeof global.addEventListener === 'function') {
    global.addEventListener('online', retryResults);
    document.addEventListener('DOMContentLoaded', retryResults);
  }
  async function updateProfile(formData, user, successMessage, fallback) {
    try {
      const data = await api('/api/perfil/actualizar', {method:'POST', body:formData});
      alert(successMessage);
      user.correo = data.correo;
      user.nombre = data.nombre;
      localStorage.setItem('datosVisionales', JSON.stringify(user));
      global.location.reload();
    } catch (error) {
      console.error('Error al actualizar:', error);
      alert(error.status ? error.message || fallback : 'Error de conexión con el servidor.');
    }
  }
  function clearSession() {
    ['datosVisionales', 'usuarioActivo', 'token', 'id_usuario'].forEach(key => localStorage.removeItem(key));
    sessionStorage.removeItem('simulacro_config');
  }
  const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]);
  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('a[href]').forEach(a => {
      if (/^(LINK_|pdfs\/)/.test(a.getAttribute('href'))) a.addEventListener('click', event => {
        event.preventDefault(); alert('Este recurso todavía no está disponible. Solicítalo a tu profesor.');
      });
    });
  });
  function importLegacyProgress() {
    const user = session();
    if (!user.id_usuario) throw new Error('Inicia sesión e identifica al propietario antes de importar.');
    for (const area of ['mat', 'lec', 'cie', 'soc', 'ing']) {
      for (const suffix of ['correctas', 'completados']) {
        const key = area + '_' + suffix;
        const legacy = localStorage.getItem(key);
        if (legacy && !storage.getItem(key)) storage.setItem(key, legacy);
      }
    }
    // Los originales se conservan. Ejecutar solo tras confirmar quién es el propietario.
  }
  global.Prep = { updateProfile, queueResult, syncResults, hasPendingResult, parse, session, storage, forUser, sameSession, api, clearSession, escapeHTML, importLegacyProgress };
})(window);

// ==========================================================================
// 1. CONTROL DE INTERFAZ DIRECTA EN EL HERO
// ==========================================================================

function alternarHeroForm(tipo) {
  const loginForm = document.getElementById("hero-login-form");
  const registroForm = document.getElementById("hero-registro-form");
  limpiarMensajes();

  if (!loginForm || !registroForm) { window.location.href="index.html"; return; }
  if (tipo === "login") {
    loginForm.style.display = "block";
    registroForm.style.display = "none";
  } else if (tipo === "registro") {
    loginForm.style.display = "none";
    registroForm.style.display = "block";
  }
}

function mostrarFeedback(contenedorId, texto, esExito = false) {
  const contenedor = document.getElementById(contenedorId) || document.getElementById("mensajeRegistro");
  if (!contenedor) return;

  let msgElement = contenedor.querySelector(".auth-msg");

  if (!msgElement) {
    msgElement = document.createElement("p");
    msgElement.className = "auth-msg";
    msgElement.style.fontSize = "14px";
    msgElement.style.marginTop = "12px";
    msgElement.style.textAlign = "center";
    msgElement.style.fontWeight = "bold";
    contenedor.appendChild(msgElement);
  }

  msgElement.textContent = texto;
  msgElement.style.color = esExito ? "#2e7d32" : "#c62828";
}

function limpiarMensajes() {
  document.querySelectorAll(".auth-msg").forEach((el) => el.remove());
}

// ==========================================================================
// 2. LOGICA DE PETICIONES (FETCH API) - JWT UPDATE
// ==========================================================================

// --- REGISTRO DE USUARIOS ---
async function registrarUsuario() {
  limpiarMensajes();

  const nombre = (document.getElementById("reg-nombre") || document.getElementById("nombreRegistro")).value.trim();
  const correo = (document.getElementById("reg-correo") || document.getElementById("correoRegistro")).value.trim();
  const password = (document.getElementById("reg-password") || document.getElementById("passwordRegistro")).value;

  const selectRol = (document.querySelector("#hero-registro-form select") || document.getElementById("rolRegistro"));
  const rol = selectRol ? selectRol.value : "estudiante";

  if (!nombre || !correo || !password) {
    mostrarFeedback("hero-registro-form", "Todos los campos son obligatorios");
    return;
  }

  try {
    const respuesta = await fetch("/api/registro", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ nombre, correo, password, rol }),
    });

    const data = await respuesta.json();

    if (!data.success) {
      mostrarFeedback("hero-registro-form", data.mensaje);
      return;
    }

    mostrarFeedback(
      "hero-registro-form",
      "¡Registro exitoso! Ya puedes ingresar.",
      true,
    );

    (document.getElementById("reg-nombre") || document.getElementById("nombreRegistro")).value = "";
    (document.getElementById("reg-correo") || document.getElementById("correoRegistro")).value = "";
    (document.getElementById("reg-password") || document.getElementById("passwordRegistro")).value = "";
    if (selectRol) selectRol.value = "estudiante";

    setTimeout(() => alternarHeroForm("login"), 1500);
  } catch (error) {
    console.error("Error en registro:", error);
    mostrarFeedback("hero-registro-form", "Error de conexión con el servidor");
  }
}

// --- INICIO DE SESIÓN CON JWT Y COOKIES ---
async function iniciarSesion() {
  limpiarMensajes();

  const correo = document.getElementById("correo").value.trim();
  const password = document.getElementById("password").value;
  const rol = document.getElementById("rol").value;

  if (!correo || !password) {
    mostrarFeedback("hero-login-form", "Completa todos los campos");
    return;
  }

  mostrarWaterLoader();

  try {
    const respuesta = await fetch("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      // IMPORTANTE: 'include' asegura que el navegador acepte y guarde la cookie HttpOnly
      credentials: "include",
      body: JSON.stringify({ correo, password, rol }),
    });

    const data = await respuesta.json();

    if (!data.success) {
      waterLoaderError(data.mensaje);
      return;
    }

    // AQUÍ ESTABA EL ERROR: Agregamos el tipo_usuario para que el panel lo reconozca
    localStorage.setItem(
      "datosVisionales",
      JSON.stringify({
        id_usuario: data.usuario.id_usuario,
        correo: data.usuario.correo,
        nombre: data.usuario.nombre,
        tipo_usuario: rol,

      }),
    );

    // === RUTAS ACTUALIZADAS ===
    const destino =
      rol === "estudiante" ? "panel-estudiante.html" : "panel-profesor.html";

    waterLoaderExito(destino);
  } catch (error) {
    console.error("Error en login:", error);
    waterLoaderError("Error de conexión con el servidor");
  }
}

/* ==========================================================================
   water-loader.js
   ========================================================================== */

let _animFrame          = null;
let _waveOffset         = 0;
let _animando           = false;
let _resultadoPendiente = null;

const DURACION = 5000;

// Lista de mensajes que irán cambiando suavemente a lo largo de los 5 segundos
const MENSAJES_CARGA = [
  'Activando tu progreso...',
  'Construyendo tu futuro...',
  'Ajustando todo para ti...',
  'Un paso más cerca de tus metas...',
  'Tu futuro está cargando...'
];

function mostrarWaterLoader() {
  document.getElementById('hero-login-form').style.display = 'none';
  document.getElementById('water-loader').style.display    = 'flex';

  _waveOffset         = 0;
  _animando           = true;
  _resultadoPendiente = null;

  document.getElementById('water-rect').setAttribute('y', '110');
  document.getElementById('wave-path').setAttribute('d', '');
  
  // Mensaje inicial limpio
  document.getElementById('loader-msg').textContent = MENSAJES_CARGA[0];

  const inicio = performance.now();

  function frame(ts) {
    const progress = Math.min((ts - inicio) / DURACION, 1);

    // Sube lineal y constante
    const yRect = 110 - (progress * 110);

    // Ola suave: amplitud pequeña, frecuencia baja
    _waveOffset += 0.5;
    let d = 'M -10 ' + yRect;
    for (let x = -10; x <= 230; x += 6) {
      const y = yRect - 3 * Math.sin((x * 0.04 + _waveOffset * 0.06) * Math.PI);
      d += ' L ' + x + ' ' + y;
    }
    d += ' L 230 120 L -10 120 Z';

    document.getElementById('water-rect').setAttribute('y', yRect);
    document.getElementById('wave-path').setAttribute('d', d);

    // === NUEVO: Control de Mensajes Dinámicos ===
    // Divide equitativamente los 5 segundos entre la cantidad de mensajes
    const indiceMensaje = Math.min(
      Math.floor(progress * MENSAJES_CARGA.length),
      MENSAJES_CARGA.length - 1
    );
    document.getElementById('loader-msg').textContent = MENSAJES_CARGA[indiceMensaje];

    if (progress < 1) {
      _animFrame = requestAnimationFrame(frame);
    } else {
      _animando = false;
      if (_resultadoPendiente) _resultadoPendiente();
    }
  }

  _animFrame = requestAnimationFrame(frame);
}

function waterLoaderExito(urlDestino) {
  const accion = function() {
    document.getElementById('water-rect').setAttribute('y', '0');
    document.getElementById('wave-path').setAttribute('d', '');
    setTimeout(function() {
      window.location.href = urlDestino || 'dashboard.html';
    }, 400);
  };

  if (_animando) {
    _resultadoPendiente = accion;
  } else {
    accion();
  }
}

function waterLoaderError(mensajeError) {
  _animando           = false;
  _resultadoPendiente = null;
  cancelAnimationFrame(_animFrame);

  document.getElementById('water-loader').style.display    = 'none';
  document.getElementById('hero-login-form').style.display = 'block';

  mostrarFeedback('hero-login-form', mensajeError || 'Correo o contraseña incorrectos.');
}

function alternarHeroForm(cual) {
  document.getElementById('water-loader').style.display = 'none';
  if (cual === 'registro') {
    document.getElementById('hero-login-form').style.display    = 'none';
    document.getElementById('hero-registro-form').style.display = 'block';
  } else {
    document.getElementById('hero-registro-form').style.display = 'none';
    document.getElementById('hero-login-form').style.display    = 'block';
  }
}
